#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

namespace FloodVR.EditorTools
{
    // Adds the split-screen stereo rig to whatever scene is open.
    //
    // IMPORTANT (see README): House.unity is regenerated by Mac 1's HouseBuilder
    // (NewScene Single), which wipes the scene. So the rig must NEVER be saved into
    // House.unity. BuildWeb calls EnsureRig() on an in-memory copy right before building.
    public static class VRRigBuilder
    {
        const float EyeSeparation = 0.064f; // metres
        const float EyeHeight     = 1.6f;   // metres
        const string StartStandPoint = "StandPoint_Hallway";

        [MenuItem("Tools/FloodVR/Add VR Rig to Active Scene")]
        public static GameObject AddRig()
        {
            var root = new GameObject("VRRig");
            Undo.RegisterCreatedObjectUndo(root, "Add VR Rig");

            var stand = new GameObject("StandPoint");          // where the adjuster stands
            stand.transform.SetParent(root.transform, false);

            var head = new GameObject("Head");
            head.transform.SetParent(root.transform, false);
            head.transform.localPosition = new Vector3(0f, EyeHeight, 0f);
            head.AddComponent<HeadLook>();
            head.AddComponent<GazeSelector>();
            head.AddComponent<AudioListener>();

            MakeEye(head.transform, "LeftEye",  -EyeSeparation * 0.5f, new Rect(0f,   0f, 0.5f, 1f), 1);
            MakeEye(head.transform, "RightEye",  EyeSeparation * 0.5f, new Rect(0.5f, 0f, 0.5f, 1f), 2);

            Selection.activeGameObject = root;
            Debug.Log("[FloodVR] VR rig added. Head carries HeadLook + GazeSelector; eyes split 0-0.5 / 0.5-1. " +
                      "Do NOT save House.unity with the rig in it - use Tools > FloodVR > Build Web.");
            return root;
        }

        // Returns the rig in the open scene, creating it if missing, then makes it match the
        // scene: eye cameras copy the scene camera's sky/clear settings, the scene's own
        // camera + audio listener are switched off, and the rig starts at StandPoint_Hallway.
        public static GameObject EnsureRig()
        {
            var look = Object.FindFirstObjectByType<HeadLook>();
            GameObject root = look != null ? look.transform.root.gameObject : AddRig();
            ConfigureForScene(root);
            return root;
        }

        static void ConfigureForScene(GameObject root)
        {
            Camera sceneCam = Camera.main;
            bool haveSceneCam = sceneCam != null && sceneCam.transform.root != root.transform;

            var headLook = root.GetComponentInChildren<HeadLook>(true);
            if (headLook != null && headLook.GetComponent<GazeSelector>() == null)
                headLook.gameObject.AddComponent<GazeSelector>();

            foreach (var eye in root.GetComponentsInChildren<Camera>(true))
            {
                if (haveSceneCam)
                {
                    // Mac 1 uses a solid-colour overcast sky + fog instead of a skybox.
                    eye.clearFlags = sceneCam.clearFlags;
                    eye.backgroundColor = sceneCam.backgroundColor;
                }
                eye.nearClipPlane = 0.05f;
                eye.farClipPlane = 100f;
                eye.allowHDR = false;
                eye.allowMSAA = false; // keep the phone build cheap
            }

            if (haveSceneCam)
            {
                sceneCam.enabled = false;
                var listener = sceneCam.GetComponent<AudioListener>();
                if (listener != null) listener.enabled = false;
            }

            var start = GameObject.Find(StartStandPoint);
            if (start != null)
            {
                Vector3 p = start.transform.position;
                root.transform.SetPositionAndRotation(
                    new Vector3(p.x, Mathf.Max(0f, p.y - EyeHeight), p.z),
                    Quaternion.Euler(0f, start.transform.eulerAngles.y, 0f));
            }
            else
            {
                Debug.LogWarning("[FloodVR] " + StartStandPoint + " not found; rig left where it was.");
            }
        }

        static void MakeEye(Transform head, string name, float xOffset, Rect rect, int depth)
        {
            var go = new GameObject(name);
            go.transform.SetParent(head, false);
            go.transform.localPosition = new Vector3(xOffset, 0f, 0f);
            var cam = go.AddComponent<Camera>();
            cam.rect = rect;
            cam.depth = depth;
            cam.nearClipPlane = 0.05f;
            cam.fieldOfView = 70f;
        }
    }
}
#endif
